import { normalizeOriginUrl } from '../../shared/test-runs/test-identity'

/**
 * CommonJS Playwright reporter Orca writes to userData and announces to its terminals.
 * It must stay dependency-free: it runs inside the user's test repo, not inside Orca.
 */
export function getOrcaPlaywrightReporterSource(): string {
  return `'use strict'
// Generated by Orca. Stores every Playwright run started in an Orca terminal.
const fs = require('node:fs')
const path = require('node:path')
const { execFileSync } = require('node:child_process')

// Why a function expression: bundling may rename the shared function.
const normalizeOriginUrl = (${normalizeOriginUrl.toString()})

const MAX_OUTPUT = 64 * 1024
const ANSI = /\\u001b\\[[0-9;]*m/g
const EXTENSIONS = {
  'image/png': '.png',
  'image/jpeg': '.jpg',
  'video/webm': '.webm',
  'application/zip': '.zip',
  'application/json': '.json',
  'text/plain': '.txt'
}

function env(name) {
  const value = process.env[name]
  return value ? value : null
}

function git(cwd, args) {
  try {
    const out = execFileSync('git', args, { cwd, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] })
    return out.trim() || null
  } catch {
    return null
  }
}

function getTrigger() {
  if (env('ORCA_TEST_RUN_TRIGGER') === 'orca') return 'orca'
  const isAgent = ['ORCA_AGENT_LAUNCH', 'ORCA_AGENT_LAUNCH_TOKEN', 'CLAUDECODE', 'CODEX_THREAD_ID'].some(env)
  return isAgent ? 'agent' : 'user'
}

function toPosix(value) {
  return value.split(path.sep).join('/')
}

function joinOutput(chunks) {
  const text = (chunks || []).map((chunk) => chunk.toString()).join('')
  return text.length > MAX_OUTPUT ? text.slice(text.length - MAX_OUTPUT) : text
}

function sanitize(name) {
  return String(name).replace(/[^a-z0-9._-]+/gi, '-').slice(0, 60) || 'attachment'
}

class OrcaReporter {
  constructor(options) {
    this.lane = (options && options.lane) || null
    // Why: listing runs reporters too, and a list is not a test run.
    this.root = process.argv.includes('--list') ? null : env('ORCA_TEST_RUNS_DIR')
    this.trigger = getTrigger()
    this.attachmentCount = 0
    this.finalCategories = new Map()
    this.hasWarned = false
  }

  printsToStdio() {
    return false
  }

  warn(error) {
    if (this.hasWarned) return
    this.hasWarned = true
    process.stderr.write('[orca] could not store the test run: ' + (error && error.message) + '\\n')
  }

  writeRun() {
    const target = path.join(this.dir, 'run.json')
    fs.writeFileSync(target + '.tmp', JSON.stringify(this.run, null, 2))
    fs.renameSync(target + '.tmp', target)
  }

  onBegin(config) {
    if (!this.root) return
    try {
      const configDir = config.configFile ? path.dirname(config.configFile) : config.rootDir
      const repoRoot = git(configDir, ['rev-parse', '--show-toplevel']) || configDir
      const originUrl = git(repoRoot, ['remote', 'get-url', 'origin'])
      this.repoRoot = repoRoot
      this.repoKey = originUrl ? normalizeOriginUrl(originUrl) : path.basename(repoRoot)
      const startedAt = Date.now()
      const id = startedAt + '-' + Math.random().toString(36).slice(2, 8)
      this.dir = path.join(this.root, 'runs', id)
      fs.mkdirSync(path.join(this.dir, 'attachments'), { recursive: true })
      this.run = {
        id,
        status: 'running',
        startedAt,
        endedAt: null,
        pid: process.pid,
        trigger: this.trigger,
        worktreeId: env('ORCA_WORKTREE_ID'),
        paneKey: env('ORCA_PANE_KEY'),
        repo: {
          root: repoRoot,
          originUrl,
          commit: git(repoRoot, ['rev-parse', 'HEAD']),
          branch: git(repoRoot, ['rev-parse', '--abbrev-ref', 'HEAD'])
        },
        configFile: config.configFile ? toPosix(path.relative(repoRoot, config.configFile)) : '',
        argv: process.argv.slice(2),
        lane: this.lane,
        totals: { passed: 0, failed: 0, skipped: 0, flaky: 0 }
      }
      fs.writeFileSync(path.join(this.dir, 'results.jsonl'), '')
      this.writeRun()
    } catch (error) {
      this.dir = null
      this.warn(error)
    }
  }

  copyAttachments(attachments) {
    const records = []
    for (const attachment of attachments || []) {
      try {
        if (!attachment.path && !attachment.body) continue
        const extension = attachment.path
          ? path.extname(attachment.path)
          : EXTENSIONS[attachment.contentType] || ''
        const file = 'attachments/' + ++this.attachmentCount + '-' + sanitize(attachment.name) + extension
        if (attachment.path) {
          fs.copyFileSync(attachment.path, path.join(this.dir, file))
        } else {
          fs.writeFileSync(path.join(this.dir, file), attachment.body)
        }
        records.push({ name: attachment.name, contentType: attachment.contentType, file })
      } catch (error) {
        this.warn(error)
      }
    }
    return records
  }

  onTestEnd(test, result) {
    if (!this.dir) return
    try {
      const file = toPosix(path.relative(this.repoRoot, test.location.file))
      const project = (test.parent.project() || { name: '' }).name
      // Why slice(3): Playwright's title path starts with the root, project and file suites.
      const titlePath = test.titlePath().slice(3)
      const identity = [this.repoKey, this.run.configFile, project, file, titlePath.join(' › ')].join('|')
      const isFinalAttempt =
        result.retry >= test.retries || result.status === test.expectedStatus || result.status === 'skipped'
      const outcome = test.outcome()
      const firstError = (result.errors || [])[0]
      const record = {
        identity,
        configFile: this.run.configFile,
        project,
        file,
        line: test.location.line,
        titlePath,
        tags: test.tags || [],
        annotations: test.annotations || [],
        expectedStatus: test.expectedStatus,
        status: result.status,
        outcome,
        retry: result.retry,
        isFinalAttempt,
        durationMs: result.duration,
        error: firstError
          ? {
              message: String(firstError.message || firstError.value || '').replace(ANSI, ''),
              location: firstError.location
                ? toPosix(path.relative(this.repoRoot, firstError.location.file)) +
                  ':' + firstError.location.line + ':' + firstError.location.column
                : null
            }
          : null,
        attachments: this.copyAttachments(result.attachments),
        stdout: joinOutput(result.stdout),
        stderr: joinOutput(result.stderr)
      }
      fs.appendFileSync(path.join(this.dir, 'results.jsonl'), JSON.stringify(record) + '\\n')
      if (isFinalAttempt) {
        const category =
          outcome === 'flaky' ? 'flaky'
          : outcome === 'skipped' ? 'skipped'
          : outcome === 'unexpected' ? 'failed'
          : 'passed'
        this.finalCategories.set(identity, category)
      }
    } catch (error) {
      this.warn(error)
    }
  }

  onEnd(result) {
    if (!this.dir) return
    try {
      const totals = { passed: 0, failed: 0, skipped: 0, flaky: 0 }
      for (const category of this.finalCategories.values()) totals[category]++
      this.run.totals = totals
      this.run.status = result.status
      this.run.endedAt = Date.now()
      this.writeRun()
    } catch (error) {
      this.warn(error)
    }
  }
}

module.exports = OrcaReporter
`
}
